using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TransPort.Web.Models;using TransPort.Web.Services;
namespace TransPort.Web.Areas.Gestion.Controllers;
[Area("Gestion"),Authorize(Roles="AdministradorGeneral,Gerente,Empleado,Operativo"),Route("gestion/abastecimientos")]
public sealed class AbastecimientosController(ITransportApiClient api,ILogger<AbastecimientosController> log):Controller
{
 [HttpGet("")]public async Task<IActionResult>Index(string?estado,string?busqueda,CancellationToken ct){try{return View(new AbastecimientoPaginaViewModel{Estado=estado,Busqueda=busqueda,Solicitudes=await api.AbastecimientosAsync(estado,busqueda,ct),Opciones=await api.AbastecimientoOpcionesAsync(ct)});}catch(Exception e)when(e is HttpRequestException or TransportApiException){log.LogError(e,"No se cargó abastecimiento");TempData["Error"]="No fue posible consultar abastecimiento.";return View(new AbastecimientoPaginaViewModel());}}
 [HttpPost("crear")]public async Task<IActionResult>Crear(AbastecimientoCrearViewModel m,CancellationToken ct){if(!ModelState.IsValid){TempData["Error"]="Revise los datos de la solicitud.";return RedirectToAction(nameof(Index));}try{var id=await api.CrearAbastecimientoAsync(m,ct);TempData["Exito"]="Solicitud creada.";return RedirectToAction(nameof(Detalle),new{id});}catch(TransportApiException e){log.LogWarning(e,"No se creó abastecimiento");TempData["Error"]="No fue posible crear; verifique giros, sedes y artículos.";return RedirectToAction(nameof(Index));}}
 [HttpGet("{id:long}")]public async Task<IActionResult>Detalle(long id,CancellationToken ct){var x=await api.AbastecimientoAsync(id,ct);return x is null?NotFound():View(x);}
 [HttpPost("{id:long}/estado")]public async Task<IActionResult>Estado(long id,string estado,string?comentario,CancellationToken ct){try{await api.CambiarEstadoAbastecimientoAsync(id,estado,comentario,ct);TempData["Exito"]="Estado actualizado.";}catch(TransportApiException e){log.LogWarning(e,"No cambió estado");TempData["Error"]="No fue posible cambiar el estado; revise la transición, permisos e inventario.";}return RedirectToAction(nameof(Detalle),new{id});}
 [HttpPost("{id:long}/comentar")]public async Task<IActionResult>Comentar(long id,string comentario,CancellationToken ct){await api.ComentarAbastecimientoAsync(id,comentario,ct);return RedirectToAction(nameof(Detalle),new{id});}
 [HttpPost("{id:long}/eliminar"),Authorize(Roles="AdministradorGeneral")]public async Task<IActionResult>Eliminar(long id,CancellationToken ct){await api.EliminarAbastecimientoAsync(id,ct);return RedirectToAction(nameof(Index));}
}
